import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第17章 雨伞","description":"","frontmatter":{},"headers":[],"relativePath":"第17章_雨伞.md","filePath":"第17章_雨伞.md"}'),r={name:"第17章_雨伞.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第17章-雨伞" tabindex="-1">第17章 雨伞 <a class="header-anchor" href="#第17章-雨伞" aria-label="Permalink to &quot;第17章 雨伞&quot;">​</a></h1><p>那年梅雨季刚冒头，天就一直阴着。</p><p>午后最后一节课是叶老师的课，粉笔落在黑板上，发出很轻的沙沙声。窗外飘起细雨，落在玻璃上，蜿蜒出细痕。我坐在靠窗的位置，能闻到雨扑进灰尘里的味道，潮湿又带着土气。我伸手摸了摸桌肚里的折叠伞，伞布有些旧，伞骨有一处不太顺。</p><p>江苒坐在前排，趁老师转身时飞快回头，指了指窗外，嘴型像在说雨大了。我点点头，示意伞还在。她才放心转回去，发尾沾着薄薄的水汽。</p><p>下课铃响时，雨已经连成线。走廊挤满了人，都堵在门口看雨。有人把书包顶在头上往外冲，溅起水花。空气里混着湿鞋的味道，还有远处食堂飘来的饭香。</p><p>我收拾好书包，把伞攥在手里。陈默凑过来，拍拍我的肩。</p><p>“带伞了。”</p><p>我晃了晃手里的伞。</p><p>“就这一把。”</p><p>正说着，江苒抱着书绕过来了。怀里几本书上放着透明小瓶，里面装满纸星星。她发丝沾了水汽，眼睛却亮亮的。</p><p>“你们也没走啊。”</p><p>陈默笑起来。</p><p>“这雨，跑出去就透了。”</p><p>江苒把书紧了紧，用外套一角盖住瓶子。</p><p>“我出门时天还好好的，没想到说下就下。”</p><p>我把伞撑开，伞面弹起，带起潮湿的风。</p><p>“一起走吧，先送你到宿舍楼下，绕点路而已。”</p><p>江苒看着外面白茫茫的雨，有些犹豫。</p><p>“三个人一把伞，怎么够。”</p><p>陈默点头。</p><p>“挤挤呗，大不了淋一点。”</p><p>江苒笑起来，轻轻点头。</p><p>“那就麻烦你们了，改天请你们喝橘子汽水。”</p><p>我们挤在一把伞下，出发了。</p><p>刚出楼门口，风就裹着雨扑进来，打在伞沿上，噼啪作响。我站在中间，江苒在左，陈默在右，肩膀贴着肩膀。路面已积水，一脚踩下去，水花溅到裤脚。鞋底踩在落叶上，软软滑滑的。</p><p>没走几步，伞就开始晃。往左偏，右边就淋到，往右偏，左边就淋到。我把伞柄握得很紧，手臂绷着。雨水顺着伞骨滴落，落在手背上，凉凉的。</p><p>江苒把书抱在胸前，走得很小心。</p><p>“你们靠紧一点，别为了让我都淋着。”</p><p>陈默抹了一把脸上的水。</p><p>“没事，淋点更精神。”</p><p>话是这么说，他的后背已湿了一块，头发也湿了，水珠顺着额头流。他还故意挺直背，想多让出一点地方。</p><p>风大了些，雨往伞底下钻。江苒的发丝贴在脸颊上，她伸手去拨，指尖沾了水。我下意识把伞往她那边斜了斜。动作很小，伞下空间却变了。她头顶雨声轻了，我这边雨声重了。</p><p>雨落在右肩上，先是几点，很快连成一片。布料吸了水，沉沉贴着皮肤，凉意渗进来。</p><p>江苒察觉到了，抬头看我。</p><p>“你那边淋到了。”</p><p>“没多少。”我说，“你抱着书，不方便躲。”</p><p>“可是肩膀都湿了。”</p><p>她伸手想把伞推回来。我没松手，反而把伞柄又往她那边送了送。</p><p>“书淋湿不好晾，衣服湿了换一件就行。”</p><p>陈默在旁看得清楚，眼珠一转，忽然退到伞外。雨立刻把他浇透，他夸张地抖抖水。</p><p>“哎呀，我突然想起来还有事。”</p><p>江苒愣住。</p><p>“这么大雨，能有什么事。”</p><p>陈默把书包往头上一顶，笑得仗义，又朝我飞快使眼色。</p><p>“去小卖部买点东西，你们先走，不用等我。我跑回去更快。”</p><p>我知道他是故意的，看出伞下太挤，干脆让出来。他那眼神分明在说，兄弟，机会给你了。</p><p>“真的不用等吗。”江苒追问。</p><p>“不用。”陈默摆手后退，“你们走你们的。”</p><p>说完，他转身冲进雨里。水花在他脚下炸开，踩水声渐渐远了，背影模糊在雨雾里。</p><p>伞下只剩我们两人。雨声变得清楚，落在伞面上，像细密的鼓点。风带着水汽灌进来，贴在脸上凉凉的。能闻到她发丝上淡淡的香，像薄荷水混着皂角味。</p><p>“跑那么快。”江苒小声嘟囔，耳朵有点红。</p><p>我把伞扶正些，想让两人都遮到。可伞就那么大，总有一边要湿。我还是习惯往她那边偏，右肩已湿透，水顺袖口淌，手臂发紧。</p><p>她忽然停下，从口袋掏出手帕。浅色布上绣着小小枇杷，边角洗得发软。</p><p>“别动。”她说。</p><p>我站在雨里没动。雨水顺伞沿滴下，在面前织成水帘。</p><p>她踮脚，把手帕按在我肩头，用力压了压，想吸掉水。手帕很快湿了，洇出深色。她皱眉，眼里有点心疼。</p><p>“都湿透了，还说没多少。”</p><p>声音被雨泡得软软的。发尾水珠蹭到手背，凉得心头一跳。</p><p>“没觉得冷。”我说。</p><p>其实有点冷，可看她认真的样子，心里又暖暖的，像喝了口温热橘子汽水。</p><p>她发现擦不干，干脆把手帕塞进我口袋，拍平。</p><p>“先垫着，回去再换。洗干净再还我，不许弄丢。”</p><p>我摸着口袋里湿湿的手帕，心跳快了些。</p><p>“好，一定还。”</p><p>路过枇杷树时，雨打叶子，哗哗作响。地上落着青色小果，被雨泡得发亮。江苒多看了两眼。</p><p>“等天晴，果子该甜了吧。”</p><p>“应该吧。”我说，“到时候来摘。”</p><p>“说好了。”她笑，眼里映着雨光，“忘了就罚你请喝汽水。”</p><p>“忘不了。”</p><p>我把伞又往她那边斜，她没推回来，只是伸手轻轻扶住伞柄下端。她的手指离我很近，能感到指尖凉意。伞柄上传来她手心的温度。</p><p>宿舍楼的灯在雨雾里亮着，暖黄一团。她小声说。</p><p>“瓶子里的纸星星，每颗都写了字。”</p><p>“写了什么。”我问。</p><p>她摇头，笑得神秘又明亮。</p><p>“不告诉你，等雨停了，心情好了，再说。”</p><p>我点头，没追问，把伞握稳，陪她慢慢走进雨里。脚下水洼映着天光，一步一碎。</p><p>到楼下时，我右半边全湿，鞋里能倒出水。她却干爽，只有鞋尖沾泥。她站在屋檐下回头看我，睫毛挂着水珠。</p><p>“今天谢谢你。”</p><p>“小事。”我说。</p><p>她咬唇，像想说什么，又没说。最后从瓶里倒出一颗粉色纸星星，塞进我手心，带着怀里的温度。</p><p>“算谢礼，不许拒绝。”</p><p>我把它攥紧，生怕打湿。</p><p>“回去快换衣服，别感冒。”她叮嘱。</p><p>“你也是。”</p><p>我转身走进雨里，走了几步回头，她还在屋檐下挥手。视线模糊，她的笑却清楚。</p><p>晚上回宿舍，陈默已换干衣服，盘腿吃海盐糖，把糖罐推过来。</p><p>“护花使者回来啦，肩膀还好吗。”</p><p>我没理他，把星星放桌上细看。每个角压得平平的，很想打开，又怕弄坏，犹豫许久，还是用书压住一角。</p><p>窗外雨声未停，落在窗台。口袋手帕还湿着，带着薄荷香。我把它晾在椅背上，看着滴水。</p><p>陈默凑过来看看，笑了。</p><p>“淋湿半边肩，心里美得很吧。”</p><p>我把糖塞进嘴里，咸甜化开，没说话，只想着她那句等雨停再说。</p><p>到底写了什么。那晚翻来覆去，耳边全是雨声，还有她扶伞柄时的凉意。</p><p>那晚我把星星放在枕边，翻身就能看见。雨点敲着窗，心里却安静得很，只盼着天快点晴。后来我才知道，那颗星星藏着一句话，要到很多天后，在同样潮湿的黄昏，才会被我真正读懂。</p>',94)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
